using System.Reflection;
using System.Runtime.InteropServices;
using System.Text.Json;
using OcctSharp.CopiedCollections;
using OcctSharp.TransferRecords;
namespace OcctSharp.Runtime.Tests;
public sealed class WriterDiagnosticsTests {
 [Theory][InlineData(WriterTransferFormat.Step)][InlineData(WriterTransferFormat.Iges)]
 public void EmptyShapeAndBoxKeepNativePerSourceOutcomes(WriterTransferFormat format)=>WithPath(path=>{using var box=ShapeFactory.CreateBox(1,2,3);using var distant=box.Transformed(ShapeTransform.CreateTranslation(20,0,0));using var empty=box.Common(distant);using var set=OwnedShapeSet.Create(empty,box);using var writer=WriterTransferSession.Create(set,format);var snapshot=writer.TransferAndWrite(path);Assert.Equal(2,snapshot.Sources.Count);Assert.Equal(format==WriterTransferFormat.Step,snapshot.Sources[0].TransferSucceeded);Assert.True(snapshot.Sources[1].TransferSucceeded);Assert.True(snapshot.WriteSucceeded);Assert.Equal(JsonSerializer.Serialize(snapshot),JsonSerializer.Serialize(writer.Snapshot()));using var read=format==WriterTransferFormat.Step?ShapeExchange.ReadStep(path):ShapeExchange.ReadIges(path);Assert.True(read.IsValid);Assert.Equal(6,read.FaceCount);});
 static void WithPath(Action<string> action){string path=Path.Combine(Path.GetTempPath(),"OcctSharp.AN."+Guid.NewGuid()+".step");try{action(path);}finally{File.Delete(path);}}
 [Theory][InlineData(WriterTransferFormat.Step)][InlineData(WriterTransferFormat.Iges)]
 public void RealFilesAndDetachedSources(WriterTransferFormat format)=>OcctSharp.Tests.Shared.BatchANWriterWorkflow.Run(format);
 [Theory][InlineData(WriterTransferFormat.Step)][InlineData(WriterTransferFormat.Iges)]
 public void EmptyInputsHaveNoFileAndNoFalseWriteSuccess(WriterTransferFormat format)=>WithPath(path=>{using var set=OwnedShapeSet.Create();using var writer=WriterTransferSession.Create(set,format);var result=writer.TransferAndWrite(path);Assert.Empty(result.Sources);Assert.Empty(result.EntityTypes);Assert.Equal(-1,result.WriteStatus);Assert.False(result.WriteSucceeded);Assert.False(File.Exists(path));Assert.Equal(JsonSerializer.Serialize(result),JsonSerializer.Serialize(writer.Snapshot()));});
 [Theory][InlineData(WriterTransferFormat.Step)][InlineData(WriterTransferFormat.Iges)]
 public void WriteFailureRetainsTransferAndMappings(WriterTransferFormat format){using var box=ShapeFactory.CreateBox(1,2,3);using var set=OwnedShapeSet.Create(box);using var writer=WriterTransferSession.Create(set,format);var result=writer.TransferAndWrite(Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString(),"absent.step"));Assert.False(result.WriteSucceeded);Assert.NotEmpty(result.EntityTypes);Assert.True(result.Sources[0].TransferSucceeded);Assert.Equal(JsonSerializer.Serialize(result),JsonSerializer.Serialize(writer.Snapshot()));}
 [Fact]public void InvalidArgumentsPreserveFreshEpoch()=>WithPath(path=>{using var box=ShapeFactory.CreateBox(1,2,3);using var set=OwnedShapeSet.Create(box);Assert.Throws<ArgumentOutOfRangeException>(()=>WriterTransferSession.Create(set,(WriterTransferFormat)2));using var writer=WriterTransferSession.Create(set);Assert.Throws<ArgumentException>(()=>writer.Snapshot());Assert.Throws<ArgumentException>(()=>writer.TransferAndWrite("a\0b"));Assert.True(writer.TransferAndWrite(path).WriteSucceeded);Assert.Throws<ArgumentException>(()=>writer.TransferAndWrite(path));});
 [Fact]public void ForeignDefaultAndOutOfBoundsIndicesAreRejected()=>WithPath(path=>{using var box=ShapeFactory.CreateBox(1,2,3);using var set=OwnedShapeSet.Create(box);using var a=WriterTransferSession.Create(set);using var b=WriterTransferSession.Create(set);var first=a.TransferAndWrite(path);var second=b.TransferAndWrite(path);Assert.Throws<ArgumentException>(()=>first.GetSource(default));Assert.Throws<ArgumentException>(()=>first.GetSource(second.SourceIndex(0)));Assert.Throws<ArgumentException>(()=>first.GetEntityType(default));Assert.Throws<ArgumentException>(()=>first.GetEntityType(second.ModelNumber(1)));Assert.Throws<ArgumentException>(()=>first.GetMapping(default));Assert.Throws<ArgumentException>(()=>first.GetMapping(second.MapIndex(1)));Assert.Throws<ArgumentOutOfRangeException>(()=>first.SourceIndex(-1));Assert.Throws<ArgumentOutOfRangeException>(()=>first.SourceIndex(1));Assert.Throws<ArgumentOutOfRangeException>(()=>first.ModelNumber(0));Assert.Throws<ArgumentOutOfRangeException>(()=>first.MapIndex(int.MaxValue));Assert.Equal(first.Sources[0],first.GetSource(first.SourceIndex(0)));});
 [Fact]public void DuplicateReversedAndLocatedInputsKeepSeparateObservations()=>WithPath(path=>{using var box=ShapeFactory.CreateBox(1,2,3);using var reverse=box.Reversed();using var moved=box.Transformed(ShapeTransform.CreateTranslation(5,0,0));using var set=OwnedShapeSet.Create(box,box,reverse,moved);using var writer=WriterTransferSession.Create(set);var snapshot=writer.TransferAndWrite(path);Assert.Equal(4,snapshot.Sources.Count);Assert.Equal(4,writer.SourceCount);Assert.All(snapshot.Sources,s=>{Assert.True(s.TransferSucceeded);Assert.NotNull(s.MapIndex);Assert.True(s.Results.HasBinder);Assert.NotEmpty(s.Results.ModelNumbers);foreach(var n in s.Results.ModelNumbers)Assert.NotEmpty(snapshot.GetEntityType(n));});Assert.True(snapshot.StatisticsAvailable);Assert.Equal(9,snapshot.Statistics.Count);Assert.IsAssignableFrom<System.Collections.ObjectModel.ReadOnlyCollection<WriterSourceResult>>(snapshot.Sources);});
 [Fact]public void DisposalAndConcurrentSnapshotReadsNeverExposeNativeStorage()=>WithPath(path=>{using var box=ShapeFactory.CreateBox(1,2,3);using var set=OwnedShapeSet.Create(box);using var writer=WriterTransferSession.Create(set);var snapshot=writer.TransferAndWrite(path);string frozen=JsonSerializer.Serialize(snapshot);var errors=new System.Collections.Concurrent.ConcurrentQueue<Exception>();Parallel.For(0,40,i=>{try{if(i==10)writer.Dispose();else Assert.Equal(frozen,JsonSerializer.Serialize(writer.Snapshot()));}catch(ObjectDisposedException){}catch(Exception e){errors.Enqueue(e);}});Assert.Empty(errors);Assert.Equal(frozen,JsonSerializer.Serialize(snapshot));Assert.Throws<ObjectDisposedException>(()=>writer.Snapshot());set.Dispose();Assert.Throws<ObjectDisposedException>(()=>WriterTransferSession.Create(set));});
 [UnmanagedFunctionPointer(CallingConvention.Cdecl)]unsafe delegate int TextRaw(nint token,byte* buffer,int capacity,out int length);
 static nint Token(object owner)=>((SafeHandle)owner.GetType().GetField("handle",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(owner)!).DangerousGetHandle();
 [Fact]public unsafe void RawTypedRegistryAndOutputBoundsRejectInvalidRequests()=>WithPath(path=>{using var box=ShapeFactory.CreateBox(1,2,3);using var set=OwnedShapeSet.Create(box);using var writer=WriterTransferSession.Create(set);writer.TransferAndWrite(path);nint library=NativeLibrary.Load(Path.Combine(AppContext.BaseDirectory,"occt","OcctSharp.Native.dll"));try{var text=Marshal.GetDelegateForFunctionPointer<TextRaw>(NativeLibrary.GetExport(library,"occtsharp_writer_diagnostics_text"));nint token=Token(writer);Assert.Equal(0,text(token,null,0,out int n));Assert.True(n>1);byte sentinel=123;Assert.NotEqual(0,text(token,&sentinel,1,out n));Assert.Equal(123,sentinel);Assert.NotEqual(0,text(Token(set),null,0,out n));Assert.Equal(0,n);Assert.NotEqual(0,text(token,null,-1,out n));writer.Dispose();Assert.NotEqual(0,text(token,null,0,out n));Assert.Equal(0,n);}finally{NativeLibrary.Free(library);}});
}
